export function renderH2H(root,ctx){const {bundle,result,options,esc,number,pct,date}=ctx,a=result.h2hAnalysis;if(!a){root.innerHTML='<p class="empty">H2H verisi hazırlanıyor.</p>';return;}
 const before=result.playerPrediction??result.baselinePrediction,after=result.prediction;
 root.innerHTML=`<div class="section-heading"><h2>İki takımın ortak geçmişi.</h2><span class="tag">H2H · SON ${a.matches.length} UYGUN MAÇ</span></div><p class="section-desc">${esc(bundle.target.home.name)} ve ${esc(bundle.target.away.name)} arasındaki geçmiş karşılaşmalar. Son 5 yıldaki en yeni 10 resmi maç, güncellik ve saha yönüyle ağırlıklandırılır. Hedef maçın sonucu hesaplamaya katılmaz.</p><div class="controls"><label class="player-global-toggle"><input type="checkbox" id="h2h-enabled" ${a.enabled?'checked':''}> H2H faktörünü kullan</label><div class="control"><label for="h2h-strength">Etki şiddeti <output>${pct(a.strength,0)}</output></label><input id="h2h-strength" type="range" min="0" max="50" step="5" value="${a.strength*100}"></div><div class="control"><label for="h2h-half-life">Geçmişin zaman ağırlığı</label><select id="h2h-half-life"><option value="180">6 ay yarı ömür</option><option value="365">1 yıl yarı ömür</option><option value="730">2 yıl yarı ömür</option></select></div></div><div class="grid two"><section class="card"><div class="card-title"><h2>H2H’nin modele etkisi</h2><span class="tag">GOL YOĞUNLUĞU</span></div><div class="mini-stats"><div><b>${number((a.factors.home-1)*100,2)}%</b><span>${esc(bundle.target.home.name)}</span></div><div><b>${number((a.factors.away-1)*100,2)}%</b><span>${esc(bundle.target.away.name)}</span></div><div><b>${number(a.effectiveMatches,1)}</b><span>ETKİN ÖRNEKLEM</span></div></div><p class="inline-note">${esc(a.reason)}</p><div class="player-baseline"><span>H2H öncesi: <b>${number(before?.homeXg,3)} – ${number(before?.awayXg,3)} gol</b></span><span>H2H ile: <b>${number(after?.homeXg,3)} – ${number(after?.awayXg,3)} gol</b></span></div><div class="callout">En olası skor: ${before?.mostLikelyScore?.home??'—'}–${before?.mostLikelyScore?.away??'—'} → ${after?.mostLikelyScore?.home??'—'}–${after?.mostLikelyScore?.away??'—'}<br>Ev / beraberlik / deplasman: ${pct(after?.outcomes?.home)} / ${pct(after?.outcomes?.draw)} / ${pct(after?.outcomes?.away)}</div><p class="inline-note">Mevcut model ortalamasına beş maçlık öncül uygulanır. H2H düzeltmesi en fazla ±%10’dur. Etki şiddeti bir doğruluk veya maç sonucu olasılığı değildir; bu katman henüz bağımsız doğrulanmadı.</p></section><section class="card"><div class="card-title"><h2>Seçilen karşılaşmaların özeti</h2><span class="kicker">HEDEF TAKIM PERSPEKTİFİ</span></div><div class="mini-stats"><div><b>${a.summary.homeWins}</b><span>${esc(bundle.target.home.name)} GALİBİYETİ</span></div><div><b>${a.summary.draws}</b><span>BERABERLİK</span></div><div><b>${a.summary.awayWins}</b><span>${esc(bundle.target.away.name)} GALİBİYETİ</span></div></div><p class="small-text">Gol toplamı: ${a.summary.homeGoals} – ${a.summary.awayGoals}<br>Maç başı gol: ${number(a.summary.homeAverage,2)} – ${number(a.summary.awayAverage,2)}<br>Aynı ev/deplasman yönünde: ${a.summary.sameVenue}/${a.matches.length} maç<br>Zaman ağırlığı toplamı: ${number(a.weightSum,2)}</p><p class="inline-note">Bu özet yalnızca listelenen uygun maçları kapsar. Aynı saha yönü 1, ters yön 0,65; farklı turnuva 0,60 ağırlık alır. Kaynağın tüm zamanlar toplamı doğrudan modele aktarılmaz.</p></section></div><div class="section-heading"><h2>Hesaba katılan H2H maçları</h2><button class="text-button" id="h2h-export">H2H JSON ↓</button></div><div class="card" style="padding:0"><div class="table-wrap"><table><thead><tr><th>TARİH</th><th>GERÇEK KARŞILAŞMA</th><th>GERÇEK SKOR</th><th>HEDEF YÖNÜNDE</th><th>AĞIRLIK</th><th></th></tr></thead><tbody>${a.matches.map(m=>`<tr><td>${date(m.date,true)}</td><td>${esc(m.home.name)} – ${esc(m.away.name)}<small>${esc(m.leagueName||'')}</small></td><td>${m.homeScore} – ${m.awayScore}</td><td>${m.homeGoals} – ${m.awayGoals}<small>${m.sameVenue?'Aynı saha yönü':'Ters saha yönü'}</small></td><td>${number(m.weight,3)}<small>${number(m.ageDays,0)} gün önce</small></td><td><a href="${esc(m.url||'https://www.fotmob.com/match/'+m.id)}" target="_blank" rel="noreferrer">FotMob ↗</a></td></tr>`).join('')}</tbody></table></div>${!a.matches.length?'<p class="empty">Tarih sınırına uygun karşılaşma bulunamadı.</p>':''}</div><details class="stat-group spaced"><summary>Dışarıda bırakılan kayıtlar · ${a.excluded.length}</summary><div class="table-wrap"><table><thead><tr><th>TARİH</th><th>MAÇ</th><th>NEDEN</th></tr></thead><tbody>${a.excluded.map(m=>`<tr><td>${date(m.date)}</td><td>${esc(m.home?.name)} – ${esc(m.away?.name)}</td><td>${esc(m.reason)}</td></tr>`).join('')}</tbody></table></div></details>`;
 const enabled=root.querySelector('#h2h-enabled'),strength=root.querySelector('#h2h-strength'),halfLife=root.querySelector('#h2h-half-life');halfLife.value=String(a.halfLife);
 enabled.onchange=()=>{options.h2hLayer=enabled.checked;ctx.recalculate();};strength.oninput=()=>strength.previousElementSibling.querySelector('output').textContent=pct(Number(strength.value)/100,0);strength.onchange=()=>{options.h2hWeight=Number(strength.value)/100;ctx.recalculate();};halfLife.onchange=()=>{options.h2hHalfLife=Number(halfLife.value);ctx.recalculate();};root.querySelector('#h2h-export').onclick=()=>ctx.download('mathgoal-h2h-'+bundle.target.id+'.json',a);
}
